  dict(id="B31", label="default user bytes 64 MiB", file=ST, old="max_bytes_per_user: 32 * 1024 * 1024,", new="max_bytes_per_user: 64 * 1024 * 1024,", tests=ROUTES),
  dict(id="B32", label="default sync response bytes 2 MiB", file=ST, old="sync_batch_bytes: 1024 * 1024,", new="sync_batch_bytes: 2 * 1024 * 1024,", tests=ROUTES),
  dict(id="B33", label="default fan-out bytes 2 MiB", file=ST, old="max_fanout_bytes_per_request: 1024 * 1024,", new="max_fanout_bytes_per_request: 2 * 1024 * 1024,", tests=ROUTES),
  dict(id="B34", label="default txn records 1001", file=ST, old="max_txns_per_device: 1000,", new="max_txns_per_device: 1001,", tests=ROUTES),
  dict(id="B35", label="sync response BYTE cap removed", file=ST, old="batch = take_within_bytes(rows, l.sync_batch_bytes)", new="batch = rows", tests=SYNC),
  dict(id="B36", label="sync response count cap removed", file=ST, old="ORDER BY stream_pos LIMIT $5", new="ORDER BY stream_pos LIMIT 100000 + 0 * $5", tests=SYNC),
  dict(id="B37", label="sync response carries nothing when ONE message exceeds the byte cap", file=ST, old="if acc != [] and total + cost > max_bytes, do:", new="if total + cost > max_bytes, do:", tests=SYNC),
  dict(id="B38", label="the seam is ignored (limits always default)", file=ST, old="value = Application.get_env(:nebu, String.to_atom(\"to_device_#{key}\"), default)", new="value = default", tests=ROUTES),
  dict(id="B39", label="a non-positive seam is accepted", file=ST, old="{key, if(is_integer(value) and value > 0, do: value, else: default)}", new="{key, value}", tests=ROUTES),

  # ── acknowledgement semantics ──
  dict(id="A01", label="ACK ON DELIVERY (the delivered rows are deleted instead of stamped)", file=ST, old="UPDATE to_device_messages SET delivery_seq = $1 WHERE stream_pos = ANY($2::bigint[]) AND delivery_seq IS NULL", new="DELETE FROM to_device_messages WHERE $1::bigint > 0 AND stream_pos = ANY($2::bigint[]) AND delivery_seq IS NULL", tests=SYNC),
  dict(id="A02", label="ack by QUEUE POSITION (delete up to the position): a late commit is lost, a forged position eats undelivered rows", file=ST, old="AND delivery_seq IS NOT NULL AND delivery_seq <= $3\"", new="AND stream_pos <= $3\"", tests=SYNC),
  dict(id="A03", label="the acknowledgement deletes nothing", file=ST, old="AND delivery_seq IS NOT NULL AND delivery_seq <= $3\"", new="AND delivery_seq IS NOT NULL AND delivery_seq <= $3 AND $3 < 0\"", tests=SYNC),
  dict(id="A04", label="ack boundary off by one (< instead of <=)", file=ST, old="AND delivery_seq IS NOT NULL AND delivery_seq <= $3\"", new="AND delivery_seq IS NOT NULL AND delivery_seq < $3\"", tests=SYNC),
  dict(id="A05", label="the acknowledgement ignores the DEVICE (acks every device of the user)", file=ST, old="DELETE FROM to_device_messages WHERE user_id = $1 AND device_id = $2 AND delivery_seq IS NOT NULL", new="DELETE FROM to_device_messages WHERE user_id = $1 AND $2::text IS NOT NULL AND delivery_seq IS NOT NULL", tests=SYNC),
  dict(id="A06", label="delivery ignores the device (a device sees the whole user's queue)", file=ST, old="WHERE user_id = $1 AND device_id = $2 AND created_at > now() - make_interval(secs => $3) AND (delivery_seq IS NULL OR delivery_seq > $4)", new="WHERE user_id = $1 AND $2::text IS NOT NULL AND created_at > now() - make_interval(secs => $3) AND (delivery_seq IS NULL OR delivery_seq > $4)", tests=SYNC + " " + SEND),
  dict(id="A07", label="a FALLBACK (foreign / unknown token) acknowledges too", file=P, old="ack = if has_since? and not fallback?, do: since_td", new="ack = if has_since?, do: since_td", tests=SYNC),
  dict(id="A08", label="no redelivery: delivered rows are never delivered again", file=ST, old="AND (delivery_seq IS NULL OR delivery_seq > $4)\n                 ORDER BY stream_pos LIMIT $5", new="AND delivery_seq IS NULL AND $4::bigint >= 0\n                 ORDER BY stream_pos LIMIT $5", tests=SYNC),
  dict(id="A09", label="the response position ignores already delivered rows (retry token acks nothing)", file=ST, old="position = Enum.max([since, seq | stamped])", new="position = Enum.max([since, seq])", tests=SYNC),
  dict(id="A10", label="the to-device position is not put into the token", file=P, old="<> if(td_pos > 0, do: \".\" <> Integer.to_string(td_pos), else: \"\")", new="<> \"\"", tests=SYNC),
  dict(id="A11", label="the to-device position of a presented token is ignored", file=P, old="{core, clamp_pos(digits), clamp_pos(List.first(rest, \"\"))}", new="{core, clamp_pos(digits), 0}", tests=SYNC),
  dict(id="A12", label="every batch is stamped with the SAME sequence value", file=ST, old="query(\"SELECT nextval('to_device_delivery_seq')\", [])", new="query(\"SELECT 1::bigint\", [])", tests=SYNC),
  dict(id="A13", label="`to_device` only emitted when there are events", file=P, old="|> Map.put(\"to_device\", %{\"events\" => td_events})", new="|> then(fn r -> if td_events == [], do: r, else: Map.put(r, \"to_device\", %{\"events\" => td_events}) end)", tests=SYNC),
  dict(id="A14", label="`to_device` events are null when empty", file=P, old="|> Map.put(\"to_device\", %{\"events\" => td_events})", new="|> Map.put(\"to_device\", %{\"events\" => if(td_events == [], do: nil, else: td_events)})", tests=SYNC),
  dict(id="A15", label="a position is accepted beyond int8 (not clamped)", file=P, old="if pos <= @max_token_pos, do: pos, else: 0", new="pos", tests="test/nebu/matrix/room_account_data_hardening_test.exs " + SYNC),
  dict(id="A16", label="an undelivered message does not make the next sync return at once (pre-check removed)", file=P, old=" or\n              Nebu.Matrix.ToDeviceStore.pending?(user, device_id, since_td)),", new="),", tests=SYNC),
  dict(id="A17", label="the pre-check ignores the token (an acknowledged message counts as pending: busy loop)", file=ST, old="def pending?(user, device, since), do: pending_query(\"(delivery_seq IS NULL OR delivery_seq > $3)\", [user, device, since])", new="def pending?(user, device, since), do: pending_query(\"(delivery_seq IS NULL OR $3::bigint >= 0)\", [user, device, since])", tests=SYNC),
  dict(id="A18", label="the pre-check always passes position 0", file=P, old="Nebu.Matrix.ToDeviceStore.pending?(user, device_id, since_td)", new="Nebu.Matrix.ToDeviceStore.pending?(user, device_id, 0)", tests=SYNC),
  dict(id="A19", label="the in-core check after the :pg join (missed wake-up window) removed", file=SRV, old=" or Nebu.Matrix.ToDeviceStore.undelivered?(user_id, device_id) do", new=" do", tests=SYNC),

  # ── wake-up ──
  dict(id="W01", label="no wake-up message is sent", file=ST, old="    targets\n    |> Enum.uniq()\n    |> Enum.each(fn {user, device} -> for pid <- :pg.get_members(\"user:#{user}\"), do: Kernel.send(pid, {:to_device, device}) end)", new="    _ = targets\n    :ok", tests=SYNC),
  dict(id="W02", label="the long poll ignores the wake-up message", file=SRV, old="if target_device == device_id, do: :wake, else: wait_loop(join_room_ids, user_id, device_id)", new="_ = target_device\n        wait_loop(join_room_ids, user_id, device_id)", tests=SYNC),
  dict(id="W03", label="every device of the user is woken", file=SRV, old="if target_device == device_id, do: :wake, else:", new="if target_device == target_device, do: :wake, else:", tests=SYNC),
  dict(id="W04", label="the wake-up goes to the wrong group", file=ST, old=":pg.get_members(\"user:#{user}\")", new=":pg.get_members(\"room:#{user}\")", tests=SYNC),
  dict(id="W05", label="the wake-up is sent for the SENDER's group", file=ST, old="    |> Enum.each(fn {user, device} -> for pid <- :pg.get_members(\"user:#{user}\"), do: Kernel.send(pid, {:to_device, device}) end)", new="    |> Enum.each(fn {_user, device} -> for pid <- :pg.get_members(\"user:@nobody:x\"), do: Kernel.send(pid, {:to_device, device}) end)", tests=SYNC),

  # ── idempotency ──
  dict(id="I01", label="every request is a fresh transaction (no dedup)", file=ST, old="{:ok, n == 1}\n    end\n  end", new="{:ok, true}\n    end\n  end", tests=SEND),
  dict(id="I02", label="the txn scope ignores the event type", file=ST, old="             [sender, sender_device, event_type, txn_id]\n           ),\n         {:ok, _} <-", new="             [sender, sender_device, \"\", txn_id]\n           ),\n         {:ok, _} <-", tests=SEND),
  dict(id="I03", label="the txn scope ignores the sending device", file=ST, old="             [sender, sender_device, event_type, txn_id]\n           ),\n         {:ok, _} <-", new="             [sender, \"\", event_type, txn_id]\n           ),\n         {:ok, _} <-", tests=SEND),
  dict(id="I04", label="the txn scope ignores the user (shared across users)", file=ST, old="             [sender, sender_device, event_type, txn_id]\n           ),\n         {:ok, _} <-", new="             [\"@shared:x\", sender_device, event_type, txn_id]\n           ),\n         {:ok, _} <-", tests=SEND),
  dict(id="I05", label="a duplicate is answered 500", file=ST, old="if fresh?, do: enqueue(sender, sender_device, event_type, entries), else: {:ok, []}", new="if fresh?, do: enqueue(sender, sender_device, event_type, entries), else: {:error, :duplicate}", tests=SEND),
  dict(id="I06", label="the txn record is written in its own statement outside the transaction (a failed enqueue keeps it)", file=ST, old="    result =\n      transact(fn ->\n        with {:ok, _} <- query(\"SELECT set_config('lock_timeout', $1::text, true)\", [\"#{@lock_timeout_ms}ms\"]),\n             :ok <- lock_sender(sender),\n             {:ok, fresh?} <- record_txn(sender, sender_device, event_type, txn_id) do\n          if fresh?, do: enqueue(sender, sender_device, event_type, entries), else: {:ok, []}\n        end\n      end)", new="    {:ok, fresh?} = record_txn(sender, sender_device, event_type, txn_id)\n\n    result =\n      transact(fn ->\n        with {:ok, _} <- query(\"SELECT set_config('lock_timeout', $1::text, true)\", [\"#{@lock_timeout_ms}ms\"]),\n             :ok <- lock_sender(sender) do\n          if fresh?, do: enqueue(sender, sender_device, event_type, entries), else: {:ok, []}\n        end\n      end)", tests=LOG),
  dict(id="I07", label="a txn record is not removed with the device", file=DKS, old="[\"to_device_messages\", \"to_device_txns\", \"device_one_time_keys\"", new="[\"to_device_messages\", \"device_one_time_keys\"", tests=PUR),
  dict(id="I08", label="the queue of a device is not removed with the device", file=DKS, old="[\"to_device_messages\", \"to_device_txns\", \"device_one_time_keys\"", new="[\"to_device_txns\", \"device_one_time_keys\"", tests=PUR),

  # ── recipient restriction and oracle-freeness ──
  dict(id="R01", label="no recipient restriction (anyone can be reached)", file=ST, old="{:ok, MapSet.new(if(sender in users, do: [sender | active], else: active))}", new="{:ok, MapSet.new(users)}", tests=SEND),
  dict(id="R06", label="an unknown device id gets a queue row", file=ST, old="MapSet.member?(existing, {u, d}), do: {u, d, c}", new="true, do: {u, d, c}", tests=SEND),
  dict(id="R07", label="`*` includes the sending device", file=ST, old="            not (user == sender and device == sender_device),\n", new="            true,\n", tests=SEND),
  dict(id="R08", label="`*` wins over an explicit device entry", file=ST, old="merged = explicit_targets ++ Enum.reject(star_targets, fn {u, d, _} -> MapSet.member?(explicit_keys, {u, d}) end)", new="merged = star_targets ++ explicit_targets\n      _ = explicit_keys", tests=SEND),
  dict(id="R09", label="`*` and an explicit entry of one device are BOTH queued (two copies)", file=ST, old="merged |> Enum.uniq_by(fn {u, d, _} -> {u, d} end) |> Enum.take(cap)", new="merged |> Enum.take(cap)", tests=SEND),
  dict(id="R10", label="`*` + explicit: both queued (no reject of the explicit device from the star set)", file=ST, old="merged = explicit_targets ++ Enum.reject(star_targets, fn {u, d, _} -> MapSet.member?(explicit_keys, {u, d}) end)", new="merged = explicit_targets ++ star_targets\n      _ = explicit_keys", tests=SEND),
  dict(id="R11", label="a deactivated recipient still gets messages", file=ST, old="WHERE u.user_id = ANY($1::text[]) AND u.is_active AND u.deletion_status IS NULL", new="WHERE u.user_id = ANY($1::text[]) AND u.deletion_status IS NULL", tests=PUR),
  dict(id="R12", label="a recipient whose erasure holds its lock is not skipped (no recipient try-lock)", file=ST, old="\n               AND pg_try_advisory_xact_lock_shared(hashtextextended('sync_global|' || u.user_id, 0))", new="", tests=ERA),
  dict(id="R13", label="the recipient lock WAITS (blocking shared lock)", file=ST, old="AND pg_try_advisory_xact_lock_shared(hashtextextended('sync_global|' || u.user_id, 0))", new="AND pg_advisory_xact_lock_shared(hashtextextended('sync_global|' || u.user_id, 0)) IS NOT NULL", tests=ERA + " " + DOCS),
  dict(id="R14", label="the sender lock is not taken", file=ST, old="    with {:ok, %{rows: [[locked?]]}} <- query(\"SELECT pg_try_advisory_xact_lock_shared(hashtextextended('sync_global|' || $1::text, 0))\", [sender]) do\n      if locked?, do: ensure_not_erased(sender), else: {:error, :lock_busy}\n    end", new="    ensure_not_erased(sender)", tests=ERA),
  dict(id="R15", label="the sender lock WAITS (blocking)", file=ST, old="SELECT pg_try_advisory_xact_lock_shared(hashtextextended('sync_global|' || $1::text, 0))", new="SELECT pg_advisory_xact_lock_shared(hashtextextended('sync_global|' || $1::text, 0)) IS NOT NULL", tests=ERA + " " + DOCS),
  dict(id="R16", label="an erased sender is not refused", file=ST, old="      {:ok, _} -> {:error, :user_erased}", new="      {:ok, _} -> :ok", tests=ERA),
  dict(id="R17", label="an erased sender is answered 500", file=H, old="{:error, :user_erased} -> error(conn, 403, \"M_USER_DEACTIVATED\", \"This account has been deactivated\")", new="{:error, :user_erased} -> failed(conn, :user_erased)", tests=ERA),
  dict(id="R18", label="the busy sender lock is answered 500 (not mapped to 429)", file=H, old="{:error, busy} when busy in [:lock_timeout, :lock_busy] -> Nebu.Web.Plugs.RateLimit.respond_limited(conn, 1)", new="{:error, busy} when busy in [:lock_timeout] -> Nebu.Web.Plugs.RateLimit.respond_limited(conn, 1)", tests=ERA),
  dict(id="R19", label="a malformed id is answered 400 (oracle: differs from a delivered request)", file=H, old="case Store.send(sender, device, event_type, txn_id, Enum.filter(entries, &storable?/1)) do", new="case (if Enum.all?(entries, &storable?/1), do: Store.send(sender, device, event_type, txn_id, entries), else: {:error, :malformed}) do", tests=SEND),
  dict(id="R20", label="a user id with a NUL reaches the database (no storable filter)", file=H, old="Enum.filter(entries, &storable?/1))", new="entries)", tests=SEND),
  dict(id="R21", label="a user id above 255 bytes is not filtered", file=H, old="Nebu.Matrix.UserId.valid?(user) and valid_device?(device)", new="is_binary(user) and not String.contains?(user, <<0>>) and valid_device?(device)", tests=SEND),
  dict(id="R22", label="a device id of 300 bytes is not filtered", file=H, old="defp valid_device?(d), do: byte_size(d) in 1..@max_id_bytes and String.valid?(d) and not String.contains?(d, <<0>>)", new="defp valid_device?(d), do: String.valid?(d) and not String.contains?(d, <<0>>)", tests=SEND),
  dict(id="R23", label="success answers a non-empty body", file=H, old=":ok -> send_json(conn, 200, %{})", new=":ok -> send_json(conn, 200, %{\"queued\" => true})", tests=SEND),
  dict(id="R24", label="stale: `*` of an unreachable user answers differently (body)", file=H, old="{:ok, entries} <- entries(messages),\n         :ok <- check_count(entries) do", new="{:ok, entries} <- entries(messages),\n         :ok <- check_count(entries),\n         :ok <- (if Enum.any?(entries, &(not storable?(&1))), do: {:error, {200, \"M_UNKNOWN\", \"skipped\"}}, else: :ok) do", tests=SEND),

  # ── validation, sizes, order ──
  dict(id="V01", label="event type up to 256 characters", file=H, old="@type_regex ~r/\\A[a-zA-Z0-9._-]{1,255}", new="@type_regex ~r/\\A[a-zA-Z0-9._-]{1,256}", tests=SEND),
  dict(id="V02", label="event type allows ':'", file=H, old="@type_regex ~r/\\A[a-zA-Z0-9._-]{1,255}", new="@type_regex ~r/\\A[a-zA-Z0-9._:-]{1,255}", tests=SEND),
  dict(id="V03", label="event type anchored with $ (trailing newline accepted)", file=H, old="@type_regex ~r/\\A[a-zA-Z0-9._-]{1,255}\\z/", new="@type_regex ~r/\\A[a-zA-Z0-9._-]{1,255}$/", tests=SEND),
  dict(id="V04", label="txn id up to 256 bytes", file=H, old="byte_size(txn) in 1..@max_id_bytes", new="byte_size(txn) in 1..(@max_id_bytes + 1)", tests=SEND),
  dict(id="V05", label="NUL in the txn id accepted", file=H, old="byte_size(txn) in 1..@max_id_bytes and String.valid?(txn) and not String.contains?(txn, <<0>>)", new="byte_size(txn) in 1..@max_id_bytes and String.valid?(txn)", tests=SEND),
  dict(id="V06", label="51 entries accepted", file=H, old="@max_entries 50", new="@max_entries 51", tests=LIM),
  dict(id="V07", label="49 entries only", file=H, old="@max_entries 50", new="@max_entries 49", tests=LIM),
  dict(id="V08", label="entries counted AFTER the unreachable ones are dropped", file=H, old="{:ok, entries} <- entries(messages),\n         :ok <- check_count(entries) do", new="{:ok, entries} <- entries(messages),\n         :ok <- check_count(Enum.filter(entries, &storable?/1)) do", tests=LIM),
  dict(id="V09", label="a non-object device entry is stored", file=H, old="{device, content}, {:ok, inner} when is_map(content) ->", new="{device, content}, {:ok, inner} ->", tests=SEND),
  dict(id="V10", label="the JSON parse error is not reported", file=H, old="if conn.assigns[:json_parse_error] == true, do: {:error, {400, \"M_NOT_JSON\", \"Request body is not valid JSON\"}}, else: :ok", new=":ok", tests=SEND),
  dict(id="V11", label="a malformed request is partly stored (valid entries of a 400 request queued first)", file=H, old="    with :ok <- check_json(conn),\n         :ok <- check_type(event_type),\n         :ok <- check_txn(txn_id),\n         {:ok, messages} <- messages(conn),\n         {:ok, entries} <- entries(messages),", new="    with :ok <- check_json(conn),\n         :ok <- check_type(event_type),\n         :ok <- check_txn(txn_id),\n         {:ok, messages} <- messages(conn),\n         _ = (Enum.each(messages, fn {u, devs} when is_map(devs) -> Store.send(conn.assigns[:current_user], device_id(conn), event_type, txn_id <> \"-early\", for({d, c} <- devs, is_map(c), do: %{user_id: u, device: d, content: Jason.encode!(c)})); _ -> :ok end)),\n         {:ok, entries} <- entries(messages),", tests=SEND),
  dict(id="V12", label="body cap 65 537", file=J, old="length: 65_536,", new="length: 65_537,", tests=LIM),
  dict(id="V13", label="body cap 65 535", file=J, old="length: 65_536,", new="length: 65_535,", tests=LIM),
  dict(id="V14", label="body cap 1 MB", file=J, old="length: 65_536,", new="length: 1_000_000,", tests=LIM),
  dict(id="V15", label="JsonBody does not skip the path (pre-auth parse)", file=J, old="if room_keys_path?(path_info) or to_device_path?(path_info), do: conn, else:", new="if room_keys_path?(path_info), do: conn, else:", tests=ROUTES),
  dict(id="V16", label="JsonBody skip compares the RAW segments (encoded spellings parse pre-auth)", file=J, old="    case path_info |> Enum.reject(&(&1 == \"\")) |> Enum.take(4) |> Enum.map(&decode_segment/1) do\n      [\"_matrix\", \"client\", _version, \"sendToDevice\"] -> true", new="    case path_info |> Enum.take(4) do\n      [\"_matrix\", \"client\", _version, \"sendToDevice\"] -> true", tests=ROUTES),
  dict(id="V17", label="JsonBody skip does not drop empty segments (`//` spellings parse pre-auth)", file=J, old="    case path_info |> Enum.reject(&(&1 == \"\")) |> Enum.take(4) |> Enum.map(&decode_segment/1) do\n      [\"_matrix\", \"client\", _version, \"sendToDevice\"] -> true", new="    case path_info |> Enum.take(4) |> Enum.map(&decode_segment/1) do\n      [\"_matrix\", \"client\", _version, \"sendToDevice\"] -> true", tests=ROUTES),
  dict(id="V18", label="the route parses the body BEFORE the rate limit", file=P, old="  put \"/client/v3/sendToDevice/:event_type/:txn_id\" do\n    conn = Nebu.Web.Plugs.RateLimit.call(conn, @to_device_rate_limit)\n\n    if conn.halted do", new="  put \"/client/v3/sendToDevice/:event_type/:txn_id\" do\n    conn = Nebu.Web.Plugs.JsonBody.parse_to_device(conn)\n    conn = if conn.halted, do: conn, else: Nebu.Web.Plugs.RateLimit.call(conn, @to_device_rate_limit)\n\n    if conn.halted do", tests=LIM),
  dict(id="V19", label="the route has no rate limit", file=P, old="    conn = Nebu.Web.Plugs.RateLimit.call(conn, @to_device_rate_limit)\n\n    if conn.halted do\n      conn\n    else\n      # a rate limit is not a concurrency limit", new="    if false do\n      conn\n    else\n      # a rate limit is not a concurrency limit", tests=LIM),
  dict(id="V20", label="rate limit burst 31", file=P, old="rate_per_min: 60, burst: 30, tier: \"to_device\"", new="rate_per_min: 60, burst: 31, tier: \"to_device\"", tests=LIM),
  dict(id="V21", label="rate limit 61 per minute", file=P, old="rate_per_min: 60, burst: 30, tier: \"to_device\"", new="rate_per_min: 61, burst: 30, tier: \"to_device\"", tests=LIM),
  dict(id="V22", label="rate limit per IP instead of per user", file=P, old="rate_per_min: 60, burst: 30, tier: \"to_device\", key: :user)", new="rate_per_min: 60, burst: 30, tier: \"to_device\")", tests=LIM),
  dict(id="V23", label="rate limit shares the tier of the account data writes", file=P, old="tier: \"to_device\"", new="tier: \"account_data\"", tests=LIM),
  dict(id="V24", label="the send slot is taken AFTER the body is read", file=P, old="        Nebu.Matrix.ToDeviceSendGate.run(conn.assigns[:current_user], fn ->\n          conn = Nebu.Web.Plugs.JsonBody.parse_to_device(conn)\n          if conn.halted, do: conn, else: Nebu.Matrix.HttpToDevice.send_to_device(conn, event_type, txn_id)\n        end)", new="        (\n          conn = Nebu.Web.Plugs.JsonBody.parse_to_device(conn)\n          Nebu.Matrix.ToDeviceSendGate.run(conn.assigns[:current_user], fn ->\n            if conn.halted, do: conn, else: Nebu.Matrix.HttpToDevice.send_to_device(conn, event_type, txn_id)\n          end)\n        )", tests=CONC),
  dict(id="V25", label="no send slots at all", file=P, old="        Nebu.Matrix.ToDeviceSendGate.run(conn.assigns[:current_user], fn ->\n          conn = Nebu.Web.Plugs.JsonBody.parse_to_device(conn)\n          if conn.halted, do: conn, else: Nebu.Matrix.HttpToDevice.send_to_device(conn, event_type, txn_id)\n        end)", new="        {:ok,\n         (\n           conn = Nebu.Web.Plugs.JsonBody.parse_to_device(conn)\n           if conn.halted, do: conn, else: Nebu.Matrix.HttpToDevice.send_to_device(conn, event_type, txn_id)\n         )}", tests=CONC),
  dict(id="V26", label="a refused slot answers 503 instead of 429", file=P, old="        :overflow -> Nebu.Web.Plugs.RateLimit.respond_limited(conn, 1)\n      end\n    end\n  end\n\n  defp room_keys_version_read", new="        :overflow -> Nebu.Matrix.Http.error(conn, 503, \"M_UNAVAILABLE\", \"busy\")\n      end\n    end\n  end\n\n  defp room_keys_version_read", tests=CONC),

  # ── send slots (gate) ──
  dict(id="G01", label="gate: no per-user limit", file=GATE, old="if user_count >= per_user or map_size(state.holders) >= per_node do", new="if map_size(state.holders) >= per_node do", tests=GT + " " + CONC),
  dict(id="G02", label="gate: no node cap", file=GATE, old="if user_count >= per_user or map_size(state.holders) >= per_node do", new="if user_count >= per_user do", tests=GT + " " + CONC),
  dict(id="G03", label="gate: default per user 5", file=GATE, old="@default_per_user 4", new="@default_per_user 5", tests=GT),
  dict(id="G04", label="gate: default per node 33", file=GATE, old="@default_per_node 32", new="@default_per_node 33", tests=GT),
  dict(id="G05", label="gate: the slot of a KILLED request is never freed", file=GATE, old="def handle_info({:DOWN, slot, :process, _pid, _reason}, state), do: {:noreply, %{state | holders: Map.delete(state.holders, slot)}}", new="def handle_info({:DOWN, _slot, :process, _pid, _reason}, state), do: {:noreply, state}", tests=GT + " " + CONC),
  dict(id="G06", label="gate: the slot of a FINISHED request is never freed", file=GATE, old="          GenServer.cast(__MODULE__, {:release, slot})", new="          :ok", tests=GT + " " + CONC),
  dict(id="G07", label="gate: a late grant after a timed-out call is kept (no cancel)", file=GATE, old="      GenServer.cast(__MODULE__, {:cancel, self()})\n      :overflow", new="      :overflow", tests=GT),
  dict(id="G08", label="gate: a gate that is not running admits (fail open)", file=GATE, old="    :exit, _reason ->\n      :overflow", new="    :exit, _reason ->\n      {:ok, make_ref()}", tests=GT),
  dict(id="G09", label="gate: the seams are not read per admission (fixed at 4 / 32)", file=GATE, old="GenServer.call(__MODULE__, {:acquire, user_id, self(), max_per_user(), max_per_node()}, 5_000)", new="GenServer.call(__MODULE__, {:acquire, user_id, self(), 4, 32}, 5_000)", tests=GT),
  dict(id="G10", label="gate: a raising holder keeps its slot (no after)", file=GATE, old="        try do\n          {:ok, fun.()}\n        after\n          GenServer.cast(__MODULE__, {:release, slot})\n        end", new="        {:ok, fun.()}", tests=GT),

  # ── TTL, purge worker ──
  dict(id="T01", label="delivery ignores the TTL", file=ST, old="WHERE user_id = $1 AND device_id = $2 AND created_at > now() - make_interval(secs => $3) AND (delivery_seq IS NULL OR delivery_seq > $4)", new="WHERE user_id = $1 AND device_id = $2 AND $3::double precision > 0 AND (delivery_seq IS NULL OR delivery_seq > $4)", tests=PUR),
  dict(id="T02", label="the pre-check ignores the TTL", file=ST, old="AND #{condition} AND created_at > now() - make_interval(secs => #{ttl_param(length(params))}))\"", new="AND #{condition} AND #{ttl_param(length(params))}::double precision > 0)\"", tests=PUR),
  dict(id="T03", label="the purge deletes everything (ignores created_at)", file=ST, old="WHERE created_at < now() - make_interval(secs => $1) LIMIT 5000 FOR UPDATE SKIP LOCKED)", new="WHERE created_at < now() + make_interval(secs => $1) LIMIT 5000 FOR UPDATE SKIP LOCKED)", tests=PUR),
  dict(id="T04", label="the purge handles only one batch of 5000", file=ST, old="      {:ok, %{num_rows: n}} when rounds < 1000 -> purge_batches(table, key, ttl, total + n, rounds + 1)", new="      {:ok, %{num_rows: n}} when rounds < 0 -> purge_batches(table, key, ttl, total + n, rounds + 1)", tests=PUR),
  dict(id="T05", label="the purge takes a waiting row lock (no SKIP LOCKED)", file=ST, old="LIMIT 5000 FOR UPDATE SKIP LOCKED)", new="LIMIT 5000 FOR UPDATE)", tests=DOCS),
  dict(id="T06", label="the purge does not touch the idempotency records", file=ST, old="         {:ok, txns} <- purge_batches(\"to_device_txns\", \"ctid\", l.txn_ttl_seconds) do", new="         txns = 0 do", tests=PUR),
  dict(id="T07", label="the purge does not touch the messages", file=ST, old="    with {:ok, messages} <- purge_batches(\"to_device_messages\", \"stream_pos\", l.ttl_seconds),", new="    with messages = 0,", tests=PUR),
  dict(id="T08", label="the cron entry is gone", file=CFG, old="       {\"41 * * * *\", Nebu.Workers.ToDevicePurgeWorker}", new="       {\"41 * * * *\", Nebu.Workers.ClientIPCheckWorker}", tests=PUR),
  dict(id="T09", label="the worker fails on every run", file=WK, old="    case Nebu.Matrix.ToDeviceStore.purge_expired() do", new="    case {:error, :boom} do", tests=PUR),
