  dict(id="L01", label="the RequestLogger captures the body of the route", file=RL, old="Nebu.Web.Plugs.RawBodyReader.room_keys_shape?(conn.request_path) or\n      Nebu.Web.Plugs.RawBodyReader.to_device_shape?(conn.request_path)", new="Nebu.Web.Plugs.RawBodyReader.room_keys_shape?(conn.request_path)", tests=LOG + " " + DOCS),
