  # ── concurrency, bounded work ──
  dict(id="C01", label="no lock_timeout in the send transaction (waits for ever behind a held record)", file=ST, old="    result =\n      transact(fn ->\n        with {:ok, _} <- query(\"SELECT set_config('lock_timeout', $1::text, true)\", [\"#{@lock_timeout_ms}ms\"]),\n             :ok <- lock_sender(sender),", new="    result =\n      transact(fn ->\n        with {:ok, _} <- query(\"SELECT 1\", []),\n             :ok <- lock_sender(sender),", tests=CONC),
  dict(id="C02", label="lock_timeout 5 seconds", file=ST, old="@lock_timeout_ms 100", new="@lock_timeout_ms 5000", tests=CONC),
  dict(id="C03", label="a lock timeout is a 500 (not mapped to 429)", file=H, old="{:error, busy} when busy in [:lock_timeout, :lock_busy] ->", new="{:error, busy} when busy in [:lock_busy] ->", tests=CONC),
  dict(id="C04", label="the existing-device lookup runs one statement PER explicit entry", file=ST, old="  defp existing_devices(explicit) do\n    with {:ok, %{rows: rows}} <-\n           query(\n             \"SELECT user_id, device_id FROM devices WHERE (user_id, device_id) IN (SELECT * FROM unnest($1::text[], $2::text[]))\",\n             [Enum.map(explicit, & &1.user_id), Enum.map(explicit, & &1.device)]\n           ) do\n      {:ok, MapSet.new(rows, fn [u, d] -> {u, d} end)}\n    end\n  end", new="  defp existing_devices(explicit) do\n    rows =\n      Enum.flat_map(explicit, fn e ->\n        {:ok, %{rows: r}} = query(\"SELECT user_id, device_id FROM devices WHERE user_id = $1 AND device_id = $2\", [e.user_id, e.device])\n        r\n      end)\n\n    {:ok, MapSet.new(rows, fn [u, d] -> {u, d} end)}\n  end", tests=CONC),
  dict(id="C05", label="the delivery stamp runs one UPDATE per message", file=ST, old="  defp stamp_new(positions) do\n    with {:ok, %{rows: [[seq]]}} <- query(\"SELECT nextval('to_device_delivery_seq')\", []),\n         {:ok, _} <- query(\"UPDATE to_device_messages SET delivery_seq = $1 WHERE stream_pos = ANY($2::bigint[]) AND delivery_seq IS NULL\", [seq, positions]) do\n      {:ok, seq}\n    end\n  end", new="  defp stamp_new(positions) do\n    with {:ok, %{rows: [[seq]]}} <- query(\"SELECT nextval('to_device_delivery_seq')\", []) do\n      Enum.each(positions, fn p -> query(\"UPDATE to_device_messages SET delivery_seq = $1 WHERE stream_pos = $2 AND delivery_seq IS NULL\", [seq, p]) end)\n      {:ok, seq}\n    end\n  end", tests=CONC),
  dict(id="C07", label="a blocking advisory lock appears in the to-device code", file=ST, old="  defp ensure_not_erased(user) do", new="  defp ensure_not_erased(user) do\n    _ = query(\"SELECT pg_advisory_xact_lock(1)\", [])", tests=DOCS),
  dict(id="C08", label="process state in the store (ETS)", file=ST, old="  defp ensure_not_erased(user) do", new="  defp ensure_not_erased(user) do\n    _ = :ets.whereis(:nebu_td_state)", tests=DOCS),
  dict(id="C09", label="the wake-up bypasses :pg (direct node call)", file=ST, old="    targets\n    |> Enum.uniq()", new="    _ = Node.list()\n    targets\n    |> Enum.uniq()", tests=DOCS),

