  dict(id="B03", label="per-device BYTE budget removed", file=ST, old="WINDOW w AS (PARTITION BY user_id, device_id ORDER BY stream_pos DESC)) s WHERE rn > $3 OR total > $5)", new="WINDOW w AS (PARTITION BY user_id, device_id ORDER BY stream_pos DESC)) s WHERE rn > $3 + 0 * $5)", tests=LIM),
  dict(id="B06", label="device byte budget off by one (>= instead of >)", file=ST, old="WINDOW w AS (PARTITION BY user_id, device_id ORDER BY stream_pos DESC)) s WHERE rn > $3 OR total > $5)", new="WINDOW w AS (PARTITION BY user_id, device_id ORDER BY stream_pos DESC)) s WHERE rn > $3 OR total >= $5)", tests=LIM),
