  dict(id="B08", label="user BYTE budget removed (fair eviction)", file=ST, old="s WHERE excess > 0 AND before < excess)", new="s WHERE excess > 1000000000000 AND before < excess)", tests=LIM),
  dict(id="B13", label="user message cap NOT fair (plain oldest first)", file=ST, old="row_number() OVER (PARTITION BY user_id ORDER BY rank DESC, stream_pos ASC) AS ord", new="row_number() OVER (PARTITION BY user_id ORDER BY stream_pos ASC) AS ord", tests=LIM),
  dict(id="F01", label="user BYTE budget NOT fair (plain oldest first)", file=ST, old="sum(cost) OVER (PARTITION BY user_id ORDER BY rank DESC, stream_pos ASC) - cost AS before", new="sum(cost) OVER (PARTITION BY user_id ORDER BY stream_pos ASC) - cost AS before", tests=LIM),
